-- Create "subscription_settings" table
CREATE TABLE `subscription_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `mail_subject` varchar(255) NOT NULL DEFAULT '', `mail_body` text NULL, `digest_day` varchar(10) NOT NULL DEFAULT '', PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "subscription_notifications" table
CREATE TABLE `subscription_notifications` (`id` int unsigned NOT NULL AUTO_INCREMENT, `kind` varchar(16) NOT NULL, `created_at` datetime NOT NULL, `read_at` datetime NULL, `mail_state` tinyint NOT NULL DEFAULT 0, `user_id` int unsigned NOT NULL, `node_id` int unsigned NOT NULL, `comment_id` int unsigned NULL, `actor_id` int unsigned NULL, `term_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `idx_subscription_notifications_user` (`user_id`, `read_at`), INDEX `idx_subscription_notifications_mail` (`mail_state`, `user_id`), INDEX `idx_subscription_notifications_created` (`created_at`), INDEX `subscriptionnotification_actor_id` (`actor_id`), INDEX `subscriptionnotification_comment_id` (`comment_id`), INDEX `subscriptionnotification_node_id` (`node_id`), INDEX `subscriptionnotification_term_id` (`term_id`), CONSTRAINT `subscription_notifications_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `subscription_notifications_nodes_node` FOREIGN KEY (`node_id`) REFERENCES `nodes` (`id`) ON DELETE CASCADE, CONSTRAINT `subscription_notifications_comments_comment` FOREIGN KEY (`comment_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE, CONSTRAINT `subscription_notifications_users_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL, CONSTRAINT `subscription_notifications_taxonomy_term_data_term` FOREIGN KEY (`term_id`) REFERENCES `taxonomy_term_data` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "subscription_user_settings" table
CREATE TABLE `subscription_user_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `mail` varchar(8) NOT NULL DEFAULT 'now', `replies` bool NOT NULL DEFAULT true, `auto_own` bool NOT NULL DEFAULT true, `auto_commented` bool NOT NULL DEFAULT true, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `uk_subscription_user_settings_user` (`user_id`), CONSTRAINT `subscription_user_settings_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "subscriptions" table
CREATE TABLE `subscriptions` (`id` int unsigned NOT NULL AUTO_INCREMENT, `muted` bool NOT NULL DEFAULT false, `token` varchar(32) NOT NULL, `created_at` datetime NOT NULL, `user_id` int unsigned NOT NULL, `node_id` int unsigned NULL, `term_id` int unsigned NULL, PRIMARY KEY (`id`), UNIQUE INDEX `uk_subscriptions_user_node` (`user_id`, `node_id`), UNIQUE INDEX `uk_subscriptions_user_term` (`user_id`, `term_id`), INDEX `idx_subscriptions_node` (`node_id`, `muted`), INDEX `idx_subscriptions_term` (`term_id`, `muted`), UNIQUE INDEX `uk_subscriptions_token` (`token`), CONSTRAINT `subscriptions_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `subscriptions_nodes_node` FOREIGN KEY (`node_id`) REFERENCES `nodes` (`id`) ON DELETE CASCADE, CONSTRAINT `subscriptions_taxonomy_term_data_term` FOREIGN KEY (`term_id`) REFERENCES `taxonomy_term_data` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
